-- ============================================================
-- SCRIPT SQL SERVER
-- Dataset: Ventas Retail - Proyecto Final Data Analytics
-- Autor: Alfredo Parente
-- Fecha: Abril 2025
-- ============================================================

-- ============================================================
-- 1. CREAR BASE DE DATOS
-- ============================================================
USE master;
GO

IF EXISTS (SELECT name FROM sys.databases WHERE name = 'RetailVentas')
BEGIN
    ALTER DATABASE RetailVentas SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE RetailVentas;
END
GO

CREATE DATABASE RetailVentas;
GO

USE RetailVentas;
GO

-- ============================================================
-- 2. CREAR TABLAS
-- ============================================================

-- Tabla CLIENTES
CREATE TABLE Clientes (
    CustomerID      VARCHAR(10)     NOT NULL PRIMARY KEY,
    Nombre          NVARCHAR(100)   NOT NULL,
    Email           VARCHAR(150)    NULL,
    Pais            NVARCHAR(50)    NOT NULL,
    Ciudad          NVARCHAR(50)    NOT NULL,
    Segmento        VARCHAR(20)     NOT NULL,
    FechaRegistro   DATE            NOT NULL
);
GO

-- Tabla PRODUCTOS
CREATE TABLE Productos (
    ProductID       VARCHAR(10)     NOT NULL PRIMARY KEY,
    Nombre_Producto NVARCHAR(100)   NOT NULL,
    Categoria       NVARCHAR(50)    NOT NULL,
    SubCategoria    NVARCHAR(50)    NOT NULL,
    PrecioUnitario  DECIMAL(10,2)   NOT NULL
);
GO

-- Tabla VENTAS
CREATE TABLE Ventas (
    TransactionID   VARCHAR(15)     NOT NULL,
    CustomerID      VARCHAR(10)     NOT NULL,
    ProductID       VARCHAR(10)     NOT NULL,
    FechaCompra     DATE            NOT NULL,
    Cantidad        INT             NULL,
    MontoTotal      DECIMAL(12,2)   NULL,
    MedioPago       VARCHAR(30)     NOT NULL,
    CONSTRAINT FK_Ventas_Clientes FOREIGN KEY (CustomerID) REFERENCES Clientes(CustomerID),
    CONSTRAINT FK_Ventas_Productos FOREIGN KEY (ProductID) REFERENCES Productos(ProductID)
);
GO

-- Índices para mejorar rendimiento de consultas
CREATE INDEX IX_Ventas_FechaCompra ON Ventas(FechaCompra);
CREATE INDEX IX_Ventas_CustomerID ON Ventas(CustomerID);
CREATE INDEX IX_Ventas_ProductID ON Ventas(ProductID);
GO

