-- ============================================================
-- 4. VERIFICACIÓN
-- ============================================================
SELECT 'Clientes' AS Tabla, COUNT(*) AS Registros FROM Clientes
UNION ALL
SELECT 'Productos', COUNT(*) FROM Productos
UNION ALL
SELECT 'Ventas', COUNT(*) FROM Ventas;
GO

-- ============================================================
-- 5. CONSULTA DEL EJERCICIO: Ventas últimos 30 días
-- ============================================================
SELECT 
    c.Nombre            AS nombre_cliente,
    v.FechaCompra       AS fecha_compra,
    v.MontoTotal        AS total_venta
FROM Ventas v
INNER JOIN Clientes c
    ON v.CustomerID = c.CustomerID
WHERE v.FechaCompra >= DATEADD(DAY, -30, GETDATE())
  AND v.MontoTotal IS NOT NULL
ORDER BY v.FechaCompra DESC;
GO
